<template><view class="account-page" :class="{'login-page':!cloudSession.user}">
  <view v-if="!cloudSession.user" class="login-hero"><view class="login-brand"><BrandMark/><text>豆物</text><text>BEAD STUDIO</text></view><view class="login-art"><image src="/static/templates/original_rabbit.png" mode="aspectFit"/><view class="login-art-note"><text>每一颗喜欢</text><text>都值得被保存</text></view></view><text class="login-title">{{loginMode==='phone'?'手机号登录':'原账号登录'}}</text><text class="login-subtitle">登录后同步作品，换个设备接着拼</text></view>
  <view v-else class="account-intro"><text class="account-title">{{sectionTitles[section]}}</text><text class="account-lead">{{sectionDescriptions[section]}}</text></view>
  <view v-if="!cloudSession.user" class="account-card login-card">
    <PhoneCodeForm v-if="loginMode==='phone'" :accepted="accepted" :available="config.smsLogin===true" :loading="configLoading" @verified="phoneLoggedIn" @busy="smsBusy=$event"><view class="privacy-check"><button class="consent-toggle" :class="{checked:accepted}" :aria-label="accepted?'已同意隐私说明':'同意隐私说明'" @tap="accepted=!accepted"><AppIcon v-if="accepted" name="check" :size="23"/></button><view><text @tap="accepted=!accepted">我已阅读并同意</text><text class="link" @tap="openPrivacy">《隐私与云端服务说明》</text></view></view></PhoneCodeForm>
    <template v-else>
      <text class="field-label">原账号</text><view class="login-input"><AppIcon name="folder" :size="31"/><input v-model.trim="account" :disabled="busy" placeholder="输入原账号" maxlength="40" :adjust-position="true"/></view>
      <text class="field-label">密码</text><view class="login-input"><AppIcon name="shield" :size="31"/><input v-model="password" :disabled="busy" :password="!showPassword" placeholder="输入密码" maxlength="128" confirm-type="go" @confirm="login"/><button class="password-toggle" :aria-label="showPassword?'隐藏密码':'显示密码'" @tap="showPassword=!showPassword">{{showPassword?'隐藏':'显示'}}</button></view>
      <view class="privacy-check"><button class="consent-toggle" :class="{checked:accepted}" :aria-label="accepted?'已同意隐私说明':'同意隐私说明'" @tap="accepted=!accepted"><AppIcon v-if="accepted" name="check" :size="23"/></button><view><text @tap="accepted=!accepted">我已阅读并同意</text><text class="link" @tap="openPrivacy">《隐私与云端服务说明》</text></view></view>
      <button class="primary-btn login-submit" :disabled="busy" @tap="login">{{busy?'正在连接…':'登录'}}</button>
      <text class="legacy-login-note">已有作品的用户，请先登录原账号，再到设置中绑定手机号。</text>
    </template>
    <button v-if="loginMode==='phone'&&!configLoading&&!config.smsLogin" class="retry-sms" @tap="load">重新检查短信服务</button>
    <button class="login-mode-switch" :disabled="busy||smsBusy" @tap="switchLoginMode">{{loginMode==='phone'?'使用原账号密码登录':'使用手机号验证码登录'}}</button>
    <!-- #ifdef MP-WEIXIN --><button v-if="config.wechatLogin" class="secondary-btn" :disabled="busy||smsBusy" @tap="wechatLogin">微信快捷登录</button><!-- #endif -->
    <button class="guest-entry" :disabled="busy||smsBusy" @tap="continueCreating">暂不登录，先去做图 <AppIcon name="chevron" :size="23"/></button>
  </view>
  <view v-if="!cloudSession.user" class="login-footer"><AppIcon name="shield" :size="23"/><text>照片本机处理 · 登录后图纸与进度自动同步</text></view>
<template v-else><template v-if="section==='settings'"><view class="account-card profile-card"><view class="profile-avatar">{{cloudSession.user.nickname.slice(0,1)}}</view><view><text class="profile-name">{{cloudSession.user.nickname}}</text><text class="subtext">{{cloudSession.user.phoneMasked||cloudSession.user.account||'微信用户'}}{{cloudSession.user.isDemo?' · 演示账号':''}}</text></view><button class="small-button" @tap="rename">改昵称</button></view>    <view class="account-links"><button v-if="cloudSession.user.role==='customer'&&!cloudSession.user.phoneMasked" @tap="bindingPhone=true">绑定手机号<text>保留作品，验证码登录 →</text></button><button v-if="cloudSession.user.phoneMasked" disabled>已绑定手机号<text>{{cloudSession.user.phoneMasked}}</text></button><button v-if="cloudSession.user.hasPassword!==false" @tap="changePassword">修改密码<text>定期维护账号安全 →</text></button><button @tap="openPrivacy">隐私与云端服务说明<text>查看 →</text></button><button @tap="logout">退出账号<text>下次登录可恢复云端作品</text></button></view>
</template><template v-if="section==='membership'"><view class="account-card entitlement-card"><view><text class="card-title">{{cloudSession.entitlements.isPro?'豆物 Pro':'普通创作者'}}</text><text class="subtext">{{cloudSession.entitlements.isPro?'有效期至 '+formatDate(cloudSession.entitlements.proUntil):'基础创作与 PNG 导出免费'}}</text></view><text class="credit-count">{{cloudSession.entitlements.exportCredits}}<text>次打印</text></text></view>
    <view v-if="!canPurchase" class="account-card"><text class="card-title">暂未开放购买</text><text class="subtext">基础做图和 PNG 导出免费，已有权益仍可使用。</text></view><template v-if="canPurchase"><view class="section-heading"><text class="card-title">创作升级</text><text class="subtext">按需要选择，权益自动到账</text></view><view v-for="plan in plans" :key="plan.id" class="account-card plan-card"><view><text class="card-title">{{plan.name}}</text><text class="subtext">{{plan.description}}</text><text class="plan-features">{{plan.features.join(' · ')}}</text></view><view class="plan-buy"><text>¥{{(plan.price_cents/100).toFixed(2)}}</text><button class="small-button" :disabled="busy" @tap="createOrder(plan)">选择套餐</button></view></view>
    </template><text v-if="canTestPay" class="test-note">当前为本地开发环境，测试付款不会真实扣款。</text></template><template v-if="section==='orders'"><view class="section-heading"><text class="card-title">我的订单</text></view><view v-if="!orders.length" class="subtext empty-note">还没有订单</view><view v-for="order in orders" :key="order.id" class="account-card order-card"><view><text class="card-title">{{order.plan_snapshot.name}}</text><text class="subtext">{{order.order_no}}</text><text class="subtext">¥{{(order.amount_cents/100).toFixed(2)}} · {{orderStatus(order.status)}}{{order.is_demo?' · 测试':''}}</text></view><view v-if="order.status==='pending'" class="order-actions"><button v-if="canTestPay" class="small-button" :disabled="busy" @tap="testPay(order)">测试付款</button><button v-if="canWechatPay" class="small-button" :disabled="busy" @tap="pay(order)">微信支付</button><button v-if="!order.payment_channel" class="plain-button" @tap="cancelOrder(order)">取消</button></view></view>
<button v-if="orders.length<orderTotal" class="secondary-btn" :disabled="busy" @tap="loadMoreOrders">加载更多订单</button></template><template v-if="section==='support'">    <view class="section-heading"><text class="card-title">咨询与定制</text><button class="plain-button" @tap="newTicket=true">新建工单 ＋</button></view><view v-for="ticket in tickets" :key="ticket.id" class="account-card ticket-row" @tap="openTicket(ticket)"><text>{{ticket.subject}}</text><text class="subtext">{{ticketStatus(ticket.status)}} →</text></view><view v-if="newTicket" class="account-card"><picker :range="['使用咨询','图纸定制']" @change="ticketKind=Number($event.detail.value)"><view class="picker-value">{{ticketKind?'图纸定制':'使用咨询'}} ▾</view></picker><input v-model.trim="ticketSubject" placeholder="咨询主题" maxlength="100"/><textarea v-model.trim="ticketBody" placeholder="描述你的问题或定制需求，请勿填写密码等敏感信息" maxlength="4000"/><button class="primary-btn" :disabled="busy" @tap="submitTicket">提交工单</button></view>
<view v-if="!tickets.length&&!newTicket" class="account-card"><text class="card-title">有什么可以帮你？</text><text class="subtext">使用问题或图纸定制，都可以在这里联系豆物。</text><button class="secondary-btn" @tap="newTicket=true">发起咨询</button></view><button v-if="tickets.length<ticketTotal" class="secondary-btn" :disabled="busy" @tap="loadMoreTickets">加载更多工单</button></template><template v-if="section==='tools'">    <view class="account-links"><button @tap="openInventory">我的豆盒<text>库存、成本与缺豆清单 →</text></button><button @tap="openWorks">云端作品<text>继续创作 →</text></button><!-- #ifndef APP-PLUS --><button @tap="importProject">导入工程文件<text>恢复可编辑图纸 →</text></button><!-- #endif --></view>
    <view v-if="legacyCount" class="migration-card"><text class="card-title">发现 {{legacyCount}} 份本机旧作品</text><text class="subtext">点击后把图纸、名称与进度上传至当前账号。重复迁移不会新增副本，本机原记录会保留。</text><button class="secondary-btn" :disabled="busy" @tap="migrate">{{busy?'迁移中…':'迁移到我的云端'}}</button></view>
<text v-if="!legacyCount" class="subtext">没有待迁移的本机旧作品。<!-- #ifndef APP-PLUS -->你也可以导入之前导出的工程文件。<!-- #endif --></text></template></template><text v-if="error" class="account-error">{{error}}</text>  <view v-if="selectedTicket" class="sheet-backdrop" @tap="selectedTicket=null"><view class="bottom-sheet" @tap.stop><view class="sheet-heading"><text class="card-title">{{selectedTicket.subject}}</text><button class="plain-button" @tap="selectedTicket=null">关闭</button></view><scroll-view scroll-y class="ticket-messages"><view v-for="message in selectedTicket.messages" :key="message.id" class="ticket-message"><text class="message-author">{{message.author_name}} · {{formatDate(message.created_at)}}</text><text>{{message.body}}</text></view></scroll-view><template v-if="selectedTicket.status!=='closed'"><textarea v-model.trim="reply" placeholder="补充说明…" maxlength="4000"/><button class="primary-btn" :disabled="busy" @tap="replyTicket">发送补充</button></template></view></view>
  <view v-if="bindingPhone" class="sheet-backdrop" @tap="closePhoneBinding"><view class="bottom-sheet phone-binding-sheet" @tap.stop><view class="sheet-heading"><text class="card-title">绑定手机号</text><button class="plain-button" :disabled="smsBusy" @tap="closePhoneBinding">取消</button></view><text class="subtext">绑定后可用验证码登录，当前作品和权益都会保留。</text><PhoneCodeForm purpose="bind" :accepted="bindAccepted" :available="config.smsLogin===true" :loading="configLoading" @busy="smsBusy=$event" @verified="phoneBound"><view class="privacy-check"><button class="consent-toggle" :class="{checked:bindAccepted}" aria-label="同意绑定手机号的隐私说明" @tap="bindAccepted=!bindAccepted"><AppIcon v-if="bindAccepted" name="check" :size="23"/></button><view><text @tap="bindAccepted=!bindAccepted">我已阅读并同意</text><text class="link" @tap="openPrivacy">《隐私与云端服务说明》</text></view></view></PhoneCodeForm></view></view>
  <!-- #ifdef H5 -->
  <view v-if="checkout" class="sheet-backdrop" @tap="checkout=null"><view class="bottom-sheet checkout-sheet" @tap.stop><view class="sheet-heading"><text class="card-title">微信扫码支付</text><button class="plain-button" @tap="checkout=null">关闭</button></view><image :src="checkout.qr" mode="aspectFit" style="width:260px;height:260px;display:block;margin:auto"/><text class="subtext">{{checkout.order.plan_snapshot.name}} · ¥{{(checkout.order.amount_cents/100).toFixed(2)}}</text><text class="privacy-note">请使用微信扫描二维码，付款后点击下方按钮查询结果。</text><button class="primary-btn" :disabled="busy" @tap="checkPayment">我已付款，查询结果</button></view></view>
  <!-- #endif -->
</view></template>
<script setup>
import {ref,watch,computed} from 'vue'
import PhoneCodeForm from '../../components/PhoneCodeForm.vue'
import BrandMark from '../../components/BrandMark.vue'
import AppIcon from '../../components/AppIcon.vue'
import {onShow,onHide,onLoad} from '@dcloudio/uni-app'
import {cloudSession,request,setSession,updateSessionUser,clearSession,refreshSession,newRequestKey} from '../../utils/cloud'
import {migrateLocalWorks,saveCloudWork} from '../../utils/cloudWorks'
import {getHistory} from '../../utils/storage'
import {clearPending} from '../../utils/appState'
const showPassword=ref(false),loginMode=ref('phone'),smsBusy=ref(false),configLoading=ref(true),bindingPhone=ref(false),bindAccepted=ref(false)
const account=ref(''),password=ref(''),accepted=ref(false),busy=ref(false),error=ref(''),plans=ref([]),orders=ref([]),tickets=ref([]),config=ref({}),legacyCount=ref(0)
let supportsCheckout = false
// #ifdef H5 || MP-WEIXIN
supportsCheckout = true
// #endif
const canWechatPay = computed(() => supportsCheckout && config.value.wechatPayment === true)
const canTestPay = computed(() => supportsCheckout && config.value.testPayments === true)
const canPurchase = computed(() => canWechatPay.value || canTestPay.value)
const newTicket=ref(false),ticketKind=ref(0),ticketSubject=ref(''),ticketBody=ref(''),selectedTicket=ref(null),reply=ref('')
const checkout=ref(null),section=ref('membership'),orderTotal=ref(0),ticketTotal=ref(0)
let pageVisible=true, pendingLoginReturn=false
const sectionTitles={membership:'创作升级',orders:'我的订单',support:'客服与定制',tools:'导入与迁移',settings:'账号设置'}
const sectionDescriptions={membership:'按需要选择，基础创作与图片导出免费。',orders:'每一笔购买，清楚可查。',support:'告诉我们遇到的问题，或聊聊你的定制想法。',tools:'把以前的创作，接回现在。',settings:'管理你的个人信息和账号安全。'}
onLoad(options=>{if(sectionTitles[options.section])section.value=options.section;uni.setNavigationBarTitle({title:cloudSession.user?sectionTitles[section.value]:'登录豆物'})})
watch([section,()=>cloudSession.user?.id],()=>uni.setNavigationBarTitle({title:cloudSession.user?sectionTitles[section.value]:'登录豆物'}))
watch(()=>cloudSession.user?.id,()=>{orders.value=[];tickets.value=[];selectedTicket.value=null;checkout.value=null;reply.value='';newTicket.value=false;ticketSubject.value='';ticketBody.value='';error.value='';bindingPhone.value=false;bindAccepted.value=false;smsBusy.value=false})
const formatDate=value=>new Date(value).toLocaleDateString('zh-CN')
const orderStatus=value=>({pending:'待付款',paid:'已付款',expired:'已过期',cancelled:'已取消'}[value]||value)
const ticketStatus=value=>({open:'待处理',in_progress:'处理中',resolved:'已解决',closed:'已关闭'}[value]||value)
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message;uni.showToast({title:e.message,icon:'none'})}finally{busy.value=false}}
async function load(){configLoading.value=true;try{config.value=await request('/config');plans.value=await request('/catalog/plans');legacyCount.value=getHistory().length;if(cloudSession.user){await refreshSession();const [o,t]=await Promise.all([request('/orders'),request('/tickets')]);orders.value=o.items;orderTotal.value=o.total;tickets.value=t.items;ticketTotal.value=t.total}}catch(e){error.value=e.message}finally{configLoading.value=false}}
onShow(()=>{pageVisible=true;if(pendingLoginReturn){pendingLoginReturn=false;returnAfterLogin();return}return load()})
onHide(()=>{pageVisible=false})
function continueCreating(){uni.switchTab({url:'/pages/index/index'})}
function switchLoginMode(){if(busy.value||smsBusy.value)return;loginMode.value=loginMode.value==='phone'?'password':'phone';password.value='';error.value=''}
function returnAfterLogin(){if(!pageVisible){pendingLoginReturn=true;return}const pages=typeof getCurrentPages==='function'?getCurrentPages():[];if(pages.length<2){uni.switchTab({url:'/pages/profile/profile'});return}uni.navigateBack({fail:()=>uni.switchTab({url:'/pages/profile/profile'})})}
function phoneLoggedIn(data){smsBusy.value=false;try{setSession(data);returnAfterLogin()}catch(e){error.value='登录信息未能保存在本机，请检查存储空间后重新获取验证码'}}
function closePhoneBinding(){if(!smsBusy.value){bindingPhone.value=false;bindAccepted.value=false}}
function phoneBound(data){smsBusy.value=false;try{updateSessionUser(data.user);bindingPhone.value=false;bindAccepted.value=false;uni.showToast({title:'手机号已绑定',icon:'success'})}catch(e){bindingPhone.value=false;error.value='手机号已验证，请重新登录以更新本机账号信息'}}
function login(){run(async()=>{if(!/^[a-zA-Z0-9_]{3,40}$/.test(account.value))throw new Error('账号需为 3–40 位字母、数字或下划线');if(!password.value)throw new Error('请输入密码');if(!accepted.value)throw new Error('请先阅读并同意隐私与云端服务说明');const data=await request('/auth/login',{method:'POST',data:{account:account.value,password:password.value,acceptedPrivacy:true}});setSession(data);password.value='';returnAfterLogin()})}
function wechatLogin(){run(async()=>{if(!accepted.value)throw new Error('请先阅读并同意隐私与云端服务说明');const result=await new Promise((resolve,reject)=>uni.login({provider:'weixin',success:resolve,fail:reject}));setSession(await request('/auth/wechat',{method:'POST',data:{code:result.code,acceptedPrivacy:true}}));await load();returnAfterLogin()})}
function logout(){return run(async()=>{try{await request('/auth/logout',{method:'POST'})}finally{clearSession();clearPending();orders.value=[];tickets.value=[]}})}
function migrate(){run(async()=>{const result=await migrateLocalWorks();uni.showToast({title:`已迁移 ${result.items.length} 份作品`,icon:'none'})})}
function rename(){uni.showModal({title:'修改昵称',editable:true,placeholderText:cloudSession.user.nickname,success:result=>{if(result.confirm&&result.content?.trim())run(async()=>{await request('/auth/me',{method:'PATCH',data:{nickname:result.content.trim()}});await refreshSession()})}})}
function createOrder(plan){if(!canPurchase.value){uni.showToast({title:'支付服务筹备中，暂未开放购买',icon:'none'});return}run(async()=>{await request('/orders',{method:'POST',data:{planId:plan.id,idempotencyKey:newRequestKey('order')}});await load();section.value='orders';uni.showToast({title:'订单已创建，请完成付款',icon:'none'})})}
function testPay(order){if(!canTestPay.value)return;uni.showModal({title:'开发环境测试付款',content:'不会真实扣款。确认后模拟付款成功并发放套餐权益，该交易不计入真实营收。',success:result=>{if(result.confirm)run(async()=>{await request(`/orders/${order.id}/test-pay`,{method:'POST'});await load();uni.showToast({title:'测试权益已到账',icon:'success'})})}})}
function pay(order){if(!canWechatPay.value){uni.showToast({title:'当前暂不支持微信付款',icon:'none'});return}run(async()=>{let mode='native';
  // #ifdef MP-WEIXIN
  mode='jsapi'
  // #endif
  const payment=await request(`/orders/${order.id}/pay`,{method:'POST',data:{mode}})
  // #ifdef MP-WEIXIN
  await new Promise((resolve,reject)=>uni.requestPayment({...payment,success:resolve,fail:reject}))
  await request(`/orders/${order.id}/sync`,{method:'POST'})
  // #endif
  // #ifdef H5
  if(payment.codeUrl){const QRCode=await import('qrcode');checkout.value={order,qr:await QRCode.toDataURL(payment.codeUrl,{width:360,margin:2})}}
  // #endif
  await load()
})}
function cancelOrder(order){run(async()=>{await request(`/orders/${order.id}/cancel`,{method:'POST'});await load()})}
function checkPayment(){run(async()=>{const order=await request(`/orders/${checkout.value.order.id}/sync`,{method:'POST'});if(order.status==='paid'){checkout.value=null;await load();uni.showToast({title:'付款成功，权益已到账',icon:'success'})}else throw new Error('暂未收到支付成功通知，请稍后再查询')})}
function submitTicket(){run(async()=>{await request('/tickets',{method:'POST',data:{subject:ticketSubject.value,kind:ticketKind.value?'custom':'support',body:ticketBody.value}});newTicket.value=false;ticketSubject.value='';ticketBody.value='';await load()})}
function loadMoreOrders(){run(async()=>{const data=await request('/orders?offset='+orders.value.length);orders.value=[...orders.value,...data.items];orderTotal.value=data.total})}
function loadMoreTickets(){run(async()=>{const data=await request('/tickets?offset='+tickets.value.length);tickets.value=[...tickets.value,...data.items];ticketTotal.value=data.total})}
async function openTicket(ticket){try{selectedTicket.value=await request(`/tickets/${ticket.id}`);reply.value=''}catch(e){error.value=e.message}}
function replyTicket(){run(async()=>{const id=selectedTicket.value.id;await request(`/tickets/${id}/messages`,{method:'POST',data:{body:reply.value,internal:false}});await openTicket({id});await load()})}
function openInventory(){uni.navigateTo({url:'/member/inventory/inventory'})}function openWorks(){uni.switchTab({url:'/pages/history/history'})}function openPrivacy(){uni.navigateTo({url:'/pages/privacy/privacy'})}
function changePassword(){uni.navigateTo({url:'/member/account/password'})}
async function importProject(){if(busy.value)return
  try{let text
  // #ifdef APP-PLUS
  throw new Error('当前 App 暂不支持导入工程文件，请使用微信小程序导入')
  // #endif
  // #ifdef H5
  const input=document.createElement('input');input.type='file';input.accept='.json,.douwu';const file=await new Promise(resolve=>{input.onchange=()=>resolve(input.files?.[0]);input.oncancel=()=>resolve(null);input.click()});if(!file)return;if(file.size>2*1024*1024)throw new Error('工程文件不能超过 2 MB');text=await file.text()
  // #endif
  // #ifdef MP-WEIXIN
  const result=await new Promise((resolve,reject)=>wx.chooseMessageFile({count:1,type:'file',extension:['json','douwu'],success:resolve,fail:reject}));const file=result.tempFiles[0];if(file.size>2*1024*1024)throw new Error('工程文件不能超过 2 MB');text=await new Promise((resolve,reject)=>wx.getFileSystemManager().readFile({filePath:file.path,encoding:'utf8',success:r=>resolve(r.data),fail:reject}))
  // #endif
  const data=JSON.parse(text);if(data.format!=='douwu-project'||data.version!==1||!data.work)throw new Error('不是有效的豆物工程文件')
  await run(async()=>{await saveCloudWork(data.work);uni.showToast({title:'工程已导入云端',icon:'success'})})
  }catch(e){if(!/cancel/.test(e.errMsg||''))error.value=e.message||'导入失败'}
}
</script>
<style scoped>
